INSERT INTO `parameters` VALUES (1,'T&A Modal','Terms and Conditions','Pop-Up Notification','html','A pop-up modal appears when the \"Terms and Conditions\" link is clicked on the login page','<p><strong style=\"font-size: 0.875rem;\">Last Updated:</strong> March 26, 2025</p><p><br></p><p>Welcome to the [NEDA Project Submission Portal] (\"Website\"). This Website is owned and operated by the National Economic and Development Authority (NEDA). By accessing or using our Website, you agree to comply with and be bound by these Terms and Conditions. If you do not agree with these terms, please do not use our Website.</p><h3><br></h3><h3>1. Acceptance of Terms</h3><p>By accessing this Website, you acknowledge that you have read, understood, and agreed to be bound by these Terms and Conditions and our Privacy Policy.</p><h3><br></h3><h3>2. Changes to Terms</h3><p>NEDA reserves the right to modify these Terms and Conditions at any time. Any changes will be posted on this page, and your continued use of the Website after such changes constitutes acceptance of the new terms.</p><h3><br></h3><h3>3. Purpose of the Website</h3><p>This Website is designed for the submission of documents related to the review and evaluation of projects. Users must ensure that all documents submitted comply with the guidelines and requirements set forth by NEDA.</p><h3><br></h3><h3>4. Use of Website</h3><p><br></p><h3><br></h3><h3>5. Intellectual Property Rights</h3><p><br></p><h3><br></h3><h3>6. Submission of Documents</h3><p><br></p><h3><br></h3><h3>7. Confidentiality and Data Protection</h3><p><br></p><h3><br></h3><h3>8. Third-Party Links</h3><p>Our Website may contain links to third-party websites. NEDA is not responsible for the content or privacy practices of these external sites.</p><h3><br></h3><h3>9. Disclaimer of Warranties</h3><p><br></p><h3><br></h3><h3>10. Limitation of Liability</h3><p>NEDA shall not be liable for any direct, indirect, incidental, consequential, or punitive damages arising from your use of the Website.</p><h3><br></h3><h3>11. Indemnification</h3><p>You agree to indemnify and hold harmless NEDA, its affiliates, and employees from any claims arising out of your use of the Website or violation of these Terms.</p><h3><br></h3><h3>12. Governing Law</h3><p>These Terms and Conditions are governed by the laws of the Republic of the Philippines. Any disputes will be resolved in the appropriate courts of jurisdiction.</p><h3><br></h3><h3>13. Contact Information</h3><p>If you have any questions about these Terms and Conditions, please contact us at thru this <strong><em><a href=\"http://icc.test/contact-us\" rel=\"noopener noreferrer\" target=\"_blank\">link</a></em></strong>.</p><p><br></p><p><br></p><p><br></p><p><strong style=\"color: rgb(230, 0, 0);\">By using this Website, you agree to these Terms and Conditions.</strong></p>','N',NULL,NULL,34,'2025-03-14 04:19:00','2025-09-16 07:40:44'),(2,'Homepage Announcement','Important Announcement!!!','Pop-Up Notification','html','A pop-up modal appears on home page','<p class=\"ql-align-center\"><strong class=\"ql-size-large\" style=\"color: rgb(230, 0, 0);\">Submission of Reviews has Resumed!</strong></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\">We hope you had a peaceful and meaningful Holy Week.</p><p class=\"ql-align-center\">Please be informed that the review of submissions has now resumed. <span style=\"color: rgb(230, 0, 0);\">All proposals submitted before or during the break are currently being processed</span>.</p><p class=\"ql-align-center\">We appreciate your patience and understanding during the holiday period. </p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\">Should you have any urgent concerns or follow-ups, feel free to reach out.</p><p class=\"ql-align-center\">Thank you!</p><p><br></p><p><br></p>','Y','2025-04-20 16:00:01','2025-06-01 15:59:59',1,'2025-04-08 06:11:42','2025-09-16 07:46:03'),(23,'Opening hours','Start of working hours for processing time (24-hour format)','Configuration','time','Starting point used to compute total processing time, should be in 24-hour format (e.g., 08:00 for 8 AM)','08:00','N',NULL,NULL,1,'2025-12-01 00:12:08','2025-12-01 00:12:08'),(24,'Closing hours','End of working hours for processing time (24-hour format)','Configuration','time','End point used to compute total processing time, should be in 24-hour format (e.g., 17:00 for 5 PM)','17:00','N',NULL,NULL,1,'2025-12-01 00:12:08','2026-01-06 09:23:02'),(25,'Include weekends','Include weekends in processing time computation (yes/no)','Configuration','boolean','Determines whether weekends are counted in the processing time calculations, set to \"yes\" to include weekends or \"no\" to exclude them','no','N',NULL,NULL,1,'2025-12-01 00:12:08','2025-12-01 00:12:08'),(26,'Include suspensions and holidays','Include suspensions and holidays in processing time computation (yes/no)','Configuration','boolean','Determines whether holidays and suspension periods are counted in the processing time calculations, set to \"yes\" to include them or \"no\" to exclude them','no','N',NULL,NULL,1,'2025-12-01 00:12:08','2026-01-05 11:57:46'),(27,'Telephone Number','ICC Core Secretariat Telephone Number','Configuration','string','Telephone number of the ICC Core Secretariat to be displayed on the website contact us page','(+632) 8631-3729','N',NULL,NULL,1,'2026-01-06 09:20:40','2026-01-06 09:20:40'),(28,'Email Address','ICC Core Secretariat Email Address','Configuration','string','Email address of the ICC Core Secretariat to be displayed on the website contact us page','icccoresecretariat@depdev.gov.ph','N',NULL,NULL,1,'2026-01-06 09:20:40','2026-01-06 09:20:40'),(29,'Office Address','ICC Core Secretariat Office Address','Configuration','string','Office address of the ICC Core Secretariat to be displayed on the website contact us page','34th Floor, SM Mega Tower, Ortigas Center, Mandaluyong City 1550','N',NULL,NULL,1,'2026-01-06 09:20:40','2026-01-06 09:20:40');
